package com.eventease.entity;

import jakarta.persistence.*;
import java.time.LocalDate;

// Registration entity - connects a Student to an Event
// This acts as the join table for the Student <-> Event many-to-many relationship
@Entity
@Table(name = "registrations")
public class Registration {

    // Primary key - auto-generated by the database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Many registrations belong to one student
    // student_id is the foreign key in the registrations table
    @ManyToOne
    @JoinColumn(name = "student_id")
    private Student student;

    // Many registrations belong to one event
    // event_id is the foreign key in the registrations table
    @ManyToOne
    @JoinColumn(name = "event_id")
    private Event event;

    // Date when the student registered for the event
    private LocalDate registrationDate;

    // Status of the registration: REGISTERED or CANCELLED
    // We never delete a registration - we only change its status
    private String status;

    // Default constructor required by JPA
    public Registration() {}

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public Student getStudent() { return student; }
    public void setStudent(Student student) { this.student = student; }

    public Event getEvent() { return event; }
    public void setEvent(Event event) { this.event = event; }

    public LocalDate getRegistrationDate() { return registrationDate; }
    public void setRegistrationDate(LocalDate registrationDate) { this.registrationDate = registrationDate; }

    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
}
